import base64
import json
import os
from typing import Any, Dict, List, Optional, Union

import boto3


def _load_document_bytes(document: Union[str, bytes, bytearray]) -> bytes:
    if isinstance(document, (bytes, bytearray)):
        return bytes(document)

    if not isinstance(document, str):
        raise TypeError("document must be a file path, base64 string, or bytes-like object")

    if os.path.isfile(document):
        with open(document, "rb") as f:
            return f.read()

    try:
        return base64.b64decode(document, validate=True)
    except Exception as exc:
        raise ValueError("document string must be a valid file path or base64-encoded content") from exc


def _confidence_value(value: Any) -> Optional[float]:
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _extract_kv(expense: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
    kv_pairs: Dict[str, Dict[str, Any]] = {}
    for kv_group in expense.get("LineItemGroups", []) or []:
        for line_item in kv_group.get("LineItems", []) or []:
            for field in line_item.get("LineItemExpenseFields", []) or []:
                name = (field.get("Type") or {}).get("Text")
                value = (field.get("ValueDetection") or {}).get("Text")
                conf = _confidence_value((field.get("ValueDetection") or {}).get("Confidence"))
                if name:
                    kv_pairs[name] = {"value": value, "confidence": conf, "raw": field}
    for field in expense.get("SummaryFields", []) or []:
        name = (field.get("Type") or {}).get("Text")
        value = (field.get("ValueDetection") or {}).get("Text")
        conf = _confidence_value((field.get("ValueDetection") or {}).get("Confidence"))
        if name:
            kv_pairs[name] = {"value": value, "confidence": conf, "raw": field}
    return kv_pairs


def _normalize_required_fields(required_fields: Optional[List[str]]) -> List[str]:
    return [str(f).strip() for f in (required_fields or []) if str(f).strip()]


def extract_and_validate_structured_fields(
    document: Union[str, bytes, bytearray],
    required_fields: Optional[List[str]] = None,
    min_confidence: float = 0.8,
    aws_region: str = "us-east-1",
) -> Dict[str, Any]:
    """
    Structured document extraction and validation using Amazon Textract AnalyzeExpense.

    Args:
        document: Path to a document file, base64-encoded document content, or raw bytes.
        required_fields: Field names that must be present in the extracted structured data.
        min_confidence: Minimum confidence threshold for each required field.
        aws_region: AWS region for Textract.

    Returns:
        A dictionary containing:
            - valid: bool
            - extracted_fields: normalized field map
            - missing_fields: list[str]
            - low_confidence_fields: list[dict]
            - raw_response: Textract response
    """
    required = _normalize_required_fields(required_fields)
    document_bytes = _load_document_bytes(document)

    client = boto3.client("textract", region_name=aws_region)
    response = client.analyze_expense(Document={"Bytes": document_bytes})

    expense_documents = response.get("ExpenseDocuments", []) or []
    extracted_fields: Dict[str, Dict[str, Any]] = {}

    for expense in expense_documents:
        extracted_fields.update(_extract_kv(expense))

    missing_fields: List[str] = []
    low_confidence_fields: List[Dict[str, Any]] = []

    for field_name in required:
        field = extracted_fields.get(field_name)
        if not field or field.get("value") in (None, ""):
            missing_fields.append(field_name)
            continue

        conf = field.get("confidence")
        if conf is None or conf < min_confidence:
            low_confidence_fields.append(
                {
                    "field": field_name,
                    "confidence": conf,
                    "value": field.get("value"),
                }
            )

    valid = not missing_fields and not low_confidence_fields

    return {
        "valid": valid,
        "extracted_fields": extracted_fields,
        "missing_fields": missing_fields,
        "low_confidence_fields": low_confidence_fields,
        "raw_response": response,
    }
